using System;
using System.Collections.Generic;
using UnityEngine;
public partial class DungeonPrototype {
 int directorRestSteps,directorWalkSteps,stepsSinceEncounter;float directorNextSpawnTime;
 Vector2Int navCachedPosition=new Vector2Int(-999,-999);int navCachedDoorStamp;
 Dictionary<Vector2Int,int> playerNavigation;readonly Dictionary<Vector2Int,int> directorSectors=new Dictionary<Vector2Int,int>();
 public readonly List<int> encounterStepIntervals=new List<int>();
 IEnumerable<DungeonDoor> NavigationDoors(){if(exitDoor!=null)yield return exitDoor;if(refugeDoor!=null)yield return refugeDoor;if(zoneTwoDoor!=null)yield return zoneTwoDoor;foreach(var door in mapDoors.Values)if(door!=null)yield return door;}
 int NavigationStamp(){int stamp=17;foreach(var door in NavigationDoors())stamp=stamp*31+(door.IsOpen?1:0);foreach(var root in refugeActors.Values)stamp=stamp*31+(root.activeSelf?1:0);foreach(var state in mapEntityStates)if(state.opened)stamp=stamp*31+state.id.GetHashCode();return stamp;}
 Dictionary<Vector2Int,int> NavigationDistances(Vector2Int start,int limit=int.MaxValue,bool respectDoors=true){var result=new Dictionary<Vector2Int,int>();if(!Open(start))return result;var queue=new Queue<Vector2Int>();result[start]=0;queue.Enqueue(start);while(queue.Count>0){var at=queue.Dequeue();int distance=result[at];if(distance>=limit)continue;foreach(var direction in directions){var next=at+direction;if(!Open(next)||result.ContainsKey(next)||RefugeNpcBlocks(next)||respectDoors&&DoorsBlock(World(at),World(next)))continue;result[next]=distance+1;queue.Enqueue(next);}}return result;}
 Dictionary<Vector2Int,int> PlayerNavigation(){int stamp=NavigationStamp();if(playerNavigation==null||navCachedPosition!=position||navCachedDoorStamp!=stamp){playerNavigation=NavigationDistances(position);navCachedPosition=position;navCachedDoorStamp=stamp;}return playerNavigation;}
 bool NavigationEnemySpacing(Vector2Int target,int index=-1){int minimum=Mathf.Max(1,EnemySettings.minimumMapSpacing);var distances=NavigationDistances(target,minimum-1);Dictionary<Vector2Int,int> old=null;for(int i=0;i<enemies.Count;i++){if(i==index||enemyObjects[i]==null)continue;int distance;if(!distances.TryGetValue(enemies[i],out distance))continue;if(index>=0){if(old==null)old=NavigationDistances(enemies[index],minimum-1);int previous;if(old.TryGetValue(enemies[i],out previous)&&distance>previous)continue;}return false;}return true;}
 bool SpawnInView(Vector2Int cell){if(!EnemySettings.spawnOutsideView)return false;Vector3 start=view!=null?view.transform.position:World(position),target=World(cell);Vector3 delta=target-start;Vector3 forward=view!=null?view.transform.forward:new Vector3(directions[heading].x,0,directions[heading].y);if(view!=null){var viewport=view.WorldToViewportPoint(target);if(viewport.z<=0||viewport.x<-.1f||viewport.x>1.1f||viewport.y<-.1f||viewport.y>1.1f)return false;}else if(Vector3.Angle(forward,delta)>44)return false;return !Physics.Linecast(start,target);}
 bool NearSpawnBoundary(Vector2Int cell){int max=Mathf.Max(EnemySettings.doorwayBufferSteps,EnemySettings.safeAreaBufferSteps);if(max<=0)return false;var nav=NavigationDistances(cell,max);foreach(var pair in nav){var region=RegionAt(pair.Key);if(pair.Value<=EnemySettings.safeAreaBufferSteps&&region!=null&&region.safeArea)return true;}foreach(var door in NavigationDoors()){Vector3 a=door.transform.position-door.transform.forward*Cell*.5f,b=door.transform.position+door.transform.forward*Cell*.5f;foreach(var p in new[]{a,b}){int distance;var at=new Vector2Int(Mathf.RoundToInt(p.x/Cell),Mathf.RoundToInt(p.z/Cell));if(nav.TryGetValue(at,out distance)&&distance<=EnemySettings.doorwayBufferSteps)return true;}}return false;}
 bool DirectedSpawnCellValid(Vector2Int cell,DungeonRegion region){int distance;return region!=null&&region.CanSpawn&&RegionAt(cell)==region&&Open(cell)&&!ReservedCell(cell)&&!RefugeNpcBlocks(cell)&&!Occupied(cell)&&PlayerNavigation().TryGetValue(cell,out distance)&&distance>=EnemySettings.minimumSpawnNavigationSteps&&NavigationEnemySpacing(cell)&&!NearSpawnBoundary(cell)&&!SpawnInView(cell);}
 void BuildDirectorSectors(){if(directorSectors.Count>0||RegionMap==null)return;int sector=0;foreach(var region in RegionMap.regions){if(region==null||!region.CanSpawn)continue;var ordered=new List<Vector2Int>(region.cells);ordered.Sort((a,b)=>a.y==b.y?a.x.CompareTo(b.x):a.y.CompareTo(b.y));foreach(var seed in ordered){if(!Open(seed)||directorSectors.ContainsKey(seed))continue;var queue=new Queue<Vector2Int>();var depth=new Dictionary<Vector2Int,int>();queue.Enqueue(seed);depth[seed]=0;directorSectors[seed]=sector;while(queue.Count>0){var at=queue.Dequeue();if(depth[at]>=EnemySettings.sectorNavigationRadius)continue;foreach(var direction in directions){var next=at+direction;if(!Open(next)||RegionAt(next)!=region||directorSectors.ContainsKey(next)||DoorsBlock(World(at),World(next)))continue;directorSectors[next]=sector;depth[next]=depth[at]+1;queue.Enqueue(next);}}sector++;}}}
 int SectorPopulation(int sector){int count=0;for(int i=0;i<enemies.Count;i++){int own;if(enemyObjects[i]!=null&&directorSectors.TryGetValue(enemies[i],out own)&&own==sector)count++;}return count;}
 bool TryDirectedSpawn(out Vector2Int result,DungeonRegion region,bool nearby){result=position;if(directorRestSteps>0)return false;BuildDirectorSectors();var nav=PlayerNavigation();var candidates=new List<Vector2Int>();int best=int.MaxValue;foreach(var pair in nav){var cell=pair.Key;var own=RegionAt(cell);if(region!=null&&own!=region||!DirectedSpawnCellValid(cell,own))continue;int sector;int population=directorSectors.TryGetValue(cell,out sector)?SectorPopulation(sector):0;if(population>=EnemySettings.desiredEnemiesPerSector)continue;
  bool preferred=pair.Value<=Mathf.Max(EnemySettings.minimumSpawnNavigationSteps,EnemySettings.preferredMaximumSpawnSteps);if(nearby&&!preferred)continue;int score=(preferred?0:10000)+population*1000+(stepsSinceEncounter>=EnemySettings.longQuietWalkSteps?pair.Value:pair.Value/4);if(score<best){best=score;candidates.Clear();}if(score==best)candidates.Add(cell);
 }if(candidates.Count==0)return false;result=candidates[UnityEngine.Random.Range(0,candidates.Count)];return true;}
 bool DirectorAllowsRespawn(){return !EnemySettings.encounterDirectorEnabled||directorRestSteps<=0&&Time.unscaledTime>=directorNextSpawnTime;}
 void DirectorRespawnOccurred(){if(EnemySettings.encounterDirectorEnabled)directorNextSpawnTime=Time.unscaledTime+EnemySettings.respawnStaggerSeconds;}
 void DirectorEncounterStarted(){if(directorWalkSteps>0)encounterStepIntervals.Add(stepsSinceEncounter);stepsSinceEncounter=0;}
 void DirectorCombatEnded(){directorRestSteps=EnemySettings.postCombatRestSteps;directorNextSpawnTime=Time.unscaledTime+EnemySettings.respawnStaggerSeconds;}
 void DirectorPlayerStep(){directorWalkSteps++;stepsSinceEncounter++;if(directorRestSteps>0)directorRestSteps--;playerNavigation=null;if(!EnemySettings.encounterDirectorEnabled||directorRestSteps>0||directorWalkSteps%Mathf.Max(1,EnemySettings.directorCheckEverySteps)!=0)return;var region=RegionAt(position);if(region==null||!region.CanSpawn)return;if(Population(region.id)>=region.enemies.maximumEnemies)return;for(int i=0;i<slots.Count;i++)if(slots[i].origin.id==region.id&&enemyObjects[i]==null&&slots[i].CanRespawn&&respawnAt[i]>=0&&respawnAt[i]<=Time.unscaledTime)return;var nav=PlayerNavigation();int nearby=0;for(int i=0;i<enemies.Count;i++){int distance;if(enemyObjects[i]!=null&&slots[i].origin.id==region.id&&nav.TryGetValue(enemies[i],out distance)&&distance<=EnemySettings.preferredMaximumSpawnSteps)nearby++;}if(nearby>=EnemySettings.desiredEnemiesPerSector)return;Vector2Int cell;if(TryDirectedSpawn(out cell,region,true))SpawnRandom(cell,region);}
}
